function CardHeadNode:Awake()
    self._headRawImage = KTool.GetComponent(self.HeadImage.gameObject, typeof(RawImageAlterable))
    self._headRawImage.IsAutoAlpha = true
    ---@type Game.Native.Common.PrefabType
    local prefabType = KTool.GetComponent(self.controller.gameObject, typeof(PrefabType))
    self._prefabType = prefabType.prefabType
    if self._prefabType == XPrefabType.SMALL_Type then
        ---小框子类型
        --self._bgImage = self.controller.gameObject:EnsureComponent(typeof(ImageAlterable))
    end
    ---@type Game.Native.Common.ID
    local idComp = self.controller.gameObject:EnsureComponent(typeof(ID))
    self._idComponent = idComp

    self._attrBgImage = self.AttrBg.gameObject:EnsureComponent(typeof(ImageAlterable))
    self._careerImage = self.CareerImage.gameObject:EnsureComponent(typeof(ImageAlterable))
    self._progressNode = self.StarGroup:GetComponent(typeof(StarProgressNode))
    self.ImgBossBg = self.controller.transform:Find("ImgBossBg")
    self.controller.ClearCache = false
    KTool.SetActive(self.LvImage.gameObject, false)
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            if not isNull(self._idComponent) then
                self.__callback(self._idComponent.id, checkInt(self.index))
            end
        end
    end

    self.ImgFetter = self.controller.transform:Find("ImgFetter")

end

