---@param cardConfId integer
---@param index integer @ 下标号
function CardHeadNode:FreshNodeByCardVo(cardConfId, index, isBig)
    self.cardVo = cardConfMgr:GetCardByRefId(cardConfId)
    self.index = index
    local lvTrans = self.LvImage
    KTool.SetActive(lvTrans.gameObject, false)
    if isTable(self.cardVo) then
        local cardVo = self.cardVo
        self:FreshBaseUI(cardVo, nil)
        ---更新水火属性图标
        --self._attrBgImage:LoadSprite(CardUtils.GetCardCareerIconPath(cardVo.career, true, true))
        CfUtils.FillImage(self.AttrBg, CardUtils.GetCardRaceIconPath(cardVo.race))
        ---@type TMPro.TextMeshProUGUI
        local textMeshProUGUI = self.LvValueTMP:GetComponent(typeof(TextMeshProUGUI))
        if not KTool.IsNull(textMeshProUGUI) then
            textMeshProUGUI.text = "1"
        end
        ---更新职业图标
        --self._careerImage:LoadSprite(CardUtils.GetCardCareerIconPath(cardVo.career, true, true))
        CfUtils.FillImage(self.CareerImage, CardUtils.GetCardRaceIconPath(cardVo.race))
        --Start group
        self._progressNode:SetStarNo(Constants.CardMaxStar, 0, 0)
        self:SetRookieStatus(false)

        ---@type JobVo
        local jobVo = cardConfMgr:GetCardCareerRowByType(cardVo.career)
        local jobIcon = isBig and jobVo.largeIcon or jobVo.icon
        self.ImgCareer:LoadSprite(jobIcon)
        --self.CareerShadow:LoadSprite(jobIcon)
        CfUtils.FillImage(self.CareerShadow, CardUtils.GetCardAttrIconPath(cardVo.attributeType, true))
    else
        printInfo("not table")
    end
end

