---@param cardVo CardVo
---@param cardDojo CardDojo
function CardHeadNode:FreshBaseUI(cardVo, cardDojo)
    if isTable(cardVo) then
        local skinId = cardVo.defaultSkin
        if cardDojo and isSet(cardDojo, "cardSkin") then
            skinId = checkNumber(cardDojo.cardSkin)
        end

        local skinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
        if skinVo then
            local rare = cardVo.rare
            local advanceLevel = cardDojo and checkNumber(cardDojo.advanceLevel) or 0
            if advanceLevel > 0 then
                rare = cardConfMgr:GetCardRare(advanceLevel, rare)
            --else
            --    printError("not found cardDojo advanceLevel")
            end
            
            ---刷新背景
            CfUtils.SetUISwitchImage(self.ImgQuality2, rare)
            CfUtils.SetUISwitchImage(self.ImgQuality1, rare)
            CfUtils.SetUISwitchImage(self.ImgQuality3, rare)
            if self._prefabType == XPrefabType.BIG_Type then
                ---更新头象图标
                CfUtils.FillImage(self._headRawImage, tostring(skinVo.cardHeadList))
                CardUtils.RefreshCardSkinEffectHead(skinVo, self._headRawImage, self.Skin_UP, self.Skin_Down)
            else
                --self._bgImage:LoadSprite(CfUtils.GetRareBgRare(rare, 2))
                CfUtils.SetUISwitchImage(self.ImgQuality, rare)
                ---小样子的背景与头像
                self._headRawImage:LoadSprite(skinVo.buffHead)
            end
            if self._prefabType == XPrefabType.BIG_Type then
                if skinVo then
                    self.CardNameTxt.text = cardVo.name
                end
            end
        end

        local isRecommend = cardDojo and cardDojo.isRecommend
        CfUtils.SetActive(self.PatrolRecommend, isRecommend)
    end
end

---FreshMonsterUI
---刷新怪物头象的逻辑
---@param monsterTypeVo MonsterTypeVo
---@param rare number 稀有度
---@param level number 等级
---@param attribute number 属性
function CardHeadNode:FreshMonsterUI(monsterTypeVo, rare, level, attribute)
    CfUtils.SetActive(self.CareerShadow, false)
    KTool.SetActive(self.StarGroup.gameObject, false)
    --KTool.SetActive(self.AttrBg.gameObject, false)
    --KTool.SetActive(self.BossProperty.gameObject, true)
    if isTable(monsterTypeVo) then
        self._idComponent.id = monsterTypeVo.id
        local textMeshProUGUI = self.LvValueTMP:GetComponent(typeof(TextMeshProUGUI))
        if not KTool.IsNull(textMeshProUGUI) then
            textMeshProUGUI.text = checkString(level)
        end

        KTool.SetActive(self.ImgBossBg.gameObject, true)
        self:SetBottomImageStatus(false)

        local skinId = monsterTypeVo.skinId
        local skinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
        local bgPath, headPath
        local isRole = monsterTypeVo.role > 0
        KTool.SetActive(self.AttrBg.gameObject, isRole)
        KTool.SetActive(self.CareerImage.gameObject, isRole)
        --KTool.SetActive(self.SkillTipsBg.gameObject, isRole)
        KTool.SetActive(self.BossProperty.gameObject, not isRole)
        if isRole then
            local cardVo = cardConfMgr:GetCardBySkinRefId(monsterTypeVo.skinId)
            bgPath = CfUtils.GetRareBgRare(cardVo.rare, 2)
            headPath = skinVo.buffHead
            --local monsterCardData = CardConfMgr:GetCardMonsterVoById(monsterTypeVo.id)
            --for i = 1, 6 do
            --    KTool.SetActive(self.SkillTipsBg.transform:Find("Image" .. i), monsterCardData.skillLevel - 1 >= i)
            --end
            --self._attrBgImage:LoadSprite(CardUtils.GetCardCareerIconPath(cardVo.career, true, true))
            CfUtils.FillImage(self.AttrBg, CardUtils.GetCardRaceIconPath(cardVo.race))
            ---更新职业图标
            --self._careerImage:LoadSprite(CardUtils.GetCardCareerIconPath(cardVo.career, true, true))
            CfUtils.FillImage(self.CareerImage, CardUtils.GetCardRaceIconPath(cardVo.race))
        else
            local monsterClass = monsterTypeVo.monsterClass
            bgPath = CardUtils.GetMonsterRareBgByMonsterClass(monsterClass)
            headPath = skinVo.buffHead

            ---@type Engine.UI.ImageAlterable
            local imageAlterable = self.BossProperty.gameObject:EnsureComponent(typeof(ImageAlterable))
            imageAlterable.isNativeSize = false
            imageAlterable:LoadSprite(UICommonUtils.GetMonsterAttributeIcon(attribute or monsterTypeVo.attribute))
        end

        CfUtils.SetUISwitchImage(self.ImgQuality2, rare)
        CfUtils.SetUISwitchImage(self.ImgQuality1, rare)

        ---小样子的背景与头像
        self:FreshBaseMonsterUI({
            headIcon = headPath,
            rare = rare,
        })
        --CfUtils.FillImage(self.HeadImage.gameObject, headPath, false)
    end
end

