--羁绊信息
function CardHeadNode:FillFettersInfo(tmDojo,ignoreAni)
    print('>> start refresh5: '.. CS.UnityEngine.Time.frameCount)  -- 打印执行帧，用于调试耗时
    CfUtils.SetActive(self.RT_FetterItem, true)
    if not tmDojo then
        self:ShowFetterItem(false)
        return
    end      
    local fetterId = tmDojo.fettersId
    local fettersCardId = tmDojo.fettersCardId
    local isHasFetters = checkNumber(fetterId) > 0 and checkNumber(fettersCardId) > 0
    self:ShowFetterItem(isHasFetters)

    if not ignoreAni then
        CfUtils.PlayAnimation(self.RT_FetterItem:Find("Content").gameObject, "FightTeamDialogTeamNodeFetterItem_Swtich")
    end

    if isHasFetters then
        local cardVo, cardDojo
        if checkNumber(tmDojo.type) == Constants.TeamMemberType.QuestLockHelperCard then
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(fetterId)
            cardDojo = {advanceLevel = 1}
        elseif checkNumber(tmDojo.type) == Constants.TeamMemberType.HelperCard then
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(tmDojo.fettersCardId)
            cardDojo = {advanceLevel = 1}
        else
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(tmDojo.fettersCardId)
            cardDojo = cardComponent:GetCardById(fetterId)
            if isNull(cardDojo) then
                -- 其他玩家的卡牌
                cardDojo = {advanceLevel = tmDojo.fettersAdvanceLevel}
            end
        end
        
        if cardVo then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
            if skinVo then
                print('>> start refresh6: '.. CS.UnityEngine.Time.frameCount)  -- 打印执行帧，用于调试耗时
                -- 头像
                CfUtils.FillImage(self.RT_ImgCardHead, skinVo.buffHead)

                -- 稀有度
                local cardRare = CardConfMgr:GetInstance():GetCardRare(checkNumber(cardDojo.advanceLevel), checkNumber(cardVo.rare))
                CfUtils.SetUISwitchImage(self.RT_ImgQuality, cardRare + 2)
                
                local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(tmDojo.cardId, cardVo.roleId)
                local isActiveFetters = fettersId > 0
                CfUtils.SetActive(self.RT_ImgIconFetter, isActiveFetters)
            end
        end
    end
end

--- 切换羁绊的显示状态
---@param state any
function CardHeadNode:ShowFetterItem(state)
    if state == true then
        KTool.SetActive(self.RT_FetterItem:Find("None"), false)
        KTool.SetActive(self.RT_FetterItem:Find("Content"), true)
    else
        KTool.SetActive(self.RT_FetterItem:Find("None"), true)
        KTool.SetActive(self.RT_FetterItem:Find("Content"), false)
    end
end

