--- 打开情绪共鸣飞行特效
---@param targetNode any
function CardHeadNode:ShowEmotionBonusFlyFX(targetNode)
    if isNotNull(self.emotionBonusFlyFxResource) then
        self:CloseEmotionBonusFlyFX()
    end
    local resource = {}
    self.emotionBonusFlyFxResource = resource
    resource.co = CoStart(function()
        resource.boomLoader      = ResourceModule.LoadBundleAsync(EmotionBonusEffectPath.Boom, nil, true)
        resource.boomMoveLoader  = ResourceModule.LoadBundleAsync(EmotionBonusEffectPath.BoomMove, nil, true)
        resource.boom2Loader     = ResourceModule.LoadBundleAsync(EmotionBonusEffectPath.BoomBoom2, nil, true)
        while not resource.boomLoader.IsCompleted 
        or not resource.boomMoveLoader.IsCompleted
        or not resource.boom2Loader.IsCompleted do
            CoYield()
        end

        -- 起爆和起飞
        resource.boomGo = GameUtils.InstantiateGoByLoader(resource.boomLoader, self.EffectStart.gameObject)
        resource.boomLoader = nil
        CoYield(0)
        resource.boomMoveGo = GameUtils.InstantiateGoByLoader(resource.boomMoveLoader, self.EffectStart.gameObject)
        resource.boomMoveLoader = nil
        CoYield(0.2)    -- 这里延迟一点再DOMove，不知道为什么FightTeamDialog的targetNode的position一开始是不对的，过一会儿才变对
        resource.tween = resource.boomMoveGo.transform:DOMove(targetNode.transform.position, 0.25, false)
        CoYield(0.25)
        resource.tween:Kill()
        resource.tween = nil
        -- 结束爆
        resource.boom2Go = GameUtils.InstantiateGoByLoader(resource.boom2Loader, targetNode.gameObject)
        resource.boom2Loader = nil
        resource.boom2Go.transform.localPosition = Vector3.zero
        CoYield(0.5)
        
        KTool.SafeDelete(resource.boomGo)
        KTool.SafeDelete(resource.boomMoveGo)
        KTool.SafeDelete(resource.boom2Go)
        resource.boomGo = nil
        resource.boomMoveGo = nil
        resource.boom2Go = nil
        resource.co = nil
        self.emotionBonusFlyFxResource = nil
    end)
end

--- 关闭情绪共鸣飞行特效
function CardHeadNode:CloseEmotionBonusFlyFX()
    if isNull(self.emotionBonusFlyFxResource) then
        return
    end

    local res = self.emotionBonusFlyFxResource
    if isNotNull(res.co) then
        CoStop(res.co)
        res.co = nil
    end

    if isNotNull(res.tween) then
        res.tween:Kill()
        res.tween = nil
    end

    if isNotNull(res.boomLoader) then
        res.boomLoader:Release()
        res.boomLoader = nil
    end

    if isNotNull(res.boomMoveLoader) then
        res.boomMoveLoader:Release()
        res.boomMoveLoader = nil
    end

    if isNotNull(res.boom2Loader) then
        res.boom2Loader:Release()
        res.boom2Loader = nil
    end

    if isNotNull(res.boomGo) then
        KTool.SafeDelete(res.boomGo)
        res.boomGo = nil
    end

    if isNotNull(res.boomMoveGo) then
        KTool.SafeDelete(res.boomMoveGo)
        res.boomMoveGo = nil
    end

    if isNotNull(res.boom2Go) then
        KTool.SafeDelete(res.boom2Go)
        res.boom2Go = nil
    end

    self.emotionBonusFlyFxResource = nil
end

return CardHeadNode